// Каждая серия — новые session_id (eval-<прогон>-<время>): прошлые BRD остаются в учёте потолков артефактов.
const T = [{"run": 1, "username": "eval: руководитель кредитования МСБ", "history": [{"role": "assistant", "content": "Здравствуйте! Я BRD-ассистент команды развития ИИ-среды. Помогу сформулировать требования к вашей задаче и подготовлю по ним BRD. Для начала расскажите в двух словах: какую задачу вы хотите решить?"}, {"role": "user", "content": "Хотим каждую неделю прогнозировать, какие клиенты малого бизнеса уйдут из банка, чтобы менеджеры успели им позвонить."}, {"role": "assistant", "content": "Понял: еженедельный прогноз оттока клиентов МСБ для удержания менеджерами. Подскажите вашу роль в этой задаче?"}, {"role": "user", "content": "Я руководитель направления кредитования МСБ, со стороны бизнеса."}, {"role": "assistant", "content": "Спасибо. В реестре действующих сервисов есть SRV-002 «Прогноз оттока розничных клиентов» — batch, еженедельно, для CRM. Не закрывает ли он вашу задачу?"}, {"role": "user", "content": "Нет, он для физлиц, а нам нужны юрлица МСБ — другие признаки и другая аудитория."}, {"role": "assistant", "content": "Принято, фиксирую отличие от SRV-002. Модель новая или уже есть готовая?"}, {"role": "user", "content": "Модель уже обучили наши DS, градиентный бустинг. Она залогирована в MLflow, код лежит в GitLab."}, {"role": "assistant", "content": "Отлично, оба обязательных условия выполнены. Что получается на выходе и кто этим пользуется?"}, {"role": "user", "content": "Список клиентов с вероятностью ухода. Его смотрят менеджеры в CRM и обзванивают тех, у кого вероятность выше порога."}, {"role": "assistant", "content": "Понял. Как часто нужен расчёт и какой объём клиентов за прогон?"}, {"role": "user", "content": "Раз в неделю, в понедельник до 8 утра, примерно 40 тысяч клиентов."}, {"role": "assistant", "content": "Batch через Airflow, понедельник до 08:00, ~40 тыс. клиентов. Какие ресурсы нужны модели: CPU, память, диск — хотя бы порядок?"}, {"role": "user", "content": "Не знаю точно, модель небольшая."}, {"role": "assistant", "content": "Предлагаю ориентир как рабочую гипотезу: 2 vCPU, 4 ГБ RAM, 10 ГБ диска на прогон. Подходит? И отдельно — нужен ли GPU?"}, {"role": "user", "content": "Да, ориентир устраивает. GPU не нужен."}, {"role": "assistant", "content": "Записал как гипотезу, подтверждённую вами; GPU не нужен. Откуда берутся данные для модели?"}, {"role": "user", "content": "Транзакции и продукты клиента из корпоративного хранилища, владелец — управление данными. Там есть ИНН и данные директоров."}, {"role": "assistant", "content": "Фиксирую: источник — КХД, есть ИНН и данные руководителей, то есть ПДн и банковская тайна. Знаете ли вы класс данных?"}, {"role": "user", "content": "Думаю, К4."}, {"role": "assistant", "content": "Записал: класс данных К4 со слов инициатора. Как поймём, что сервис успешен: какая бизнес-метрика и целевое значение?"}, {"role": "user", "content": "Снизить отток МСБ на 10% за полгода. По модели DS говорили ROC-AUC 0.78 на тесте."}, {"role": "assistant", "content": "Записал: бизнес-цель −10% оттока за 6 месяцев, ROC-AUC 0.78 на тесте. Кто должен получать алерты, если расчёт в понедельник не прошёл?"}, {"role": "user", "content": "Наш аналитик Ирина и дежурный DevOps."}, {"role": "assistant", "content": "Понял. Резюме: еженедельный batch-прогноз оттока клиентов МСБ (~40 тыс., пн до 08:00, Airflow); модель есть в MLflow, код в GitLab; выход — вероятность ухода в CRM для менеджеров; ресурсы 2 vCPU/4 ГБ/10 ГБ — гипотеза, подтверждена; GPU не нужен; данные из КХД с ПДн и банковской тайной, класс К4; цель −10% оттока за полгода, ROC-AUC 0.78; алерты — аналитик и дежурный DevOps; отличие от SRV-002 — юрлица МСБ. Всё верно? Если да — сформирую BRD."}, {"role": "user", "content": "Да, всё верно."}, {"role": "assistant", "content": "Спасибо! Формирую BRD."}]}, {"run": 2, "username": "eval: продакт кредитных карт", "history": [{"role": "assistant", "content": "Здравствуйте! Я BRD-ассистент команды развития ИИ-среды. Помогу сформулировать требования к вашей задаче и подготовлю по ним BRD. Для начала расскажите в двух словах: какую задачу вы хотите решить?"}, {"role": "user", "content": "Нужно в реальном времени оценивать заявки на кредитные карты физлиц, чтобы сразу давать предодобрение в мобильном приложении."}, {"role": "assistant", "content": "Понял: онлайн-скоринг заявок на кредитные карты для предодобрения. Вы со стороны бизнеса или разработки?"}, {"role": "user", "content": "Я продакт-менеджер кредитных карт."}, {"role": "assistant", "content": "Спасибо. В реестре есть SRV-011 «Антифрод-скоринг заявок на потребкредит» — он оценивает риск мошенничества. Ваша задача — кредитный риск или тоже антифрод?"}, {"role": "user", "content": "Кредитный риск, не мошенничество. SRV-011 мы используем отдельно, он остаётся."}, {"role": "assistant", "content": "Принято. Модель уже обучена?"}, {"role": "user", "content": "Да, модель есть, она в MLflow. А вот код писал подрядчик, он у нас в архиве на сетевом диске, в GitLab его нет."}, {"role": "assistant", "content": "Фиксирую: модель в MLflow есть, кода в GitLab нет — это открытый пункт до деплоя, команда может помочь с переносом. Кто вызывает сервис и как?"}, {"role": "user", "content": "Бэкенд мобильного приложения, синхронно, на каждую заявку ждёт ответ."}, {"role": "assistant", "content": "Синхронный вызов. Какая допустимая задержка ответа?"}, {"role": "user", "content": "Не больше 300 миллисекунд на 95-м перцентиле."}, {"role": "assistant", "content": "p95 ≤ 300 мс. Сколько запросов в секунду в обычное время и в пик?"}, {"role": "user", "content": "Обычно около 20 в секунду, в пик во время акций до 60."}, {"role": "assistant", "content": "Записал: ~20 RPS, пики до 60. Что делать, если сервис не ответил вовремя или модель не уверена?"}, {"role": "user", "content": "Тогда заявка уходит на обычное ручное рассмотрение, как сейчас."}, {"role": "assistant", "content": "Fallback — ручное рассмотрение. Какие данные получает модель?"}, {"role": "user", "content": "Анкета заявителя и кредитная история из бюро. Это ПДн, банковская тайна, класс К4."}, {"role": "assistant", "content": "Фиксирую: ПДн, банковская тайна, К4; меры защиты согласуются с ИБ отдельно. Нужна ли интерпретируемость решения для клиента или регулятора?"}, {"role": "user", "content": "Да, при отказе нужно уметь объяснить основные причины."}, {"role": "assistant", "content": "Записал требование к объяснимости. Какие ресурсы нужны сервису?"}, {"role": "user", "content": "Не знаю, это лучше спросить у DS."}, {"role": "assistant", "content": "Фиксирую ресурсы как открытый вопрос к DS. Как измерим успех?"}, {"role": "user", "content": "Доля автоматических предодобрений должна вырасти с 0 до 40%, при этом дефолтность не выше текущей."}, {"role": "assistant", "content": "Резюме: онлайн-скоринг кредитного риска заявок на карты (не антифрод, SRV-011 остаётся); синхронный вызов из бэкенда приложения, p95 ≤ 300 мс, ~20 RPS, пики до 60; fallback — ручное рассмотрение; модель в MLflow, кода в GitLab нет — открытый пункт; данные — анкета и бюро, ПДн, банковская тайна, К4; нужна объяснимость отказов; ресурсы — открытый вопрос к DS; цель — 40% автопредодобрений без роста дефолтности. Всё верно?"}, {"role": "user", "content": "Да, верно."}, {"role": "assistant", "content": "Спасибо! Формирую BRD."}]}, {"run": 3, "username": "eval: руководитель операционного блока юрлиц", "history": [{"role": "assistant", "content": "Здравствуйте! Я BRD-ассистент команды развития ИИ-среды. Помогу сформулировать требования к вашей задаче и подготовлю по ним BRD. Для начала расскажите в двух словах: какую задачу вы хотите решить?"}, {"role": "user", "content": "Хотим автоматически разбирать входящие письма от корпоративных клиентов и раскидывать их по отделам."}, {"role": "assistant", "content": "Понял: классификация писем юрлиц для маршрутизации. В реестре есть SRV-004 «Классификация обращений клиентов» — онлайн, для чатов и почты контакт-центра. Не подходит ли он?"}, {"role": "user", "content": "Не знаю, мы его не смотрели. У нас своя почта операционного блока, тематики другие."}, {"role": "assistant", "content": "Фиксирую как открытый вопрос: проверить применимость SRV-004. Модель уже есть?"}, {"role": "user", "content": "Нет, модели пока нет, хотим, чтобы её сделали."}, {"role": "assistant", "content": "Значит, новая модель: в MLflow и GitLab пока ничего нет — это открытые пункты до деплоя. Сколько писем приходит?"}, {"role": "user", "content": "Примерно 3 тысячи в день."}, {"role": "assistant", "content": "~3000 писем в день. Нужно классифицировать каждое письмо сразу при поступлении или можно раз в час пачкой?"}, {"role": "user", "content": "Не знаю, наверное лучше сразу."}, {"role": "assistant", "content": "Записал: желательна обработка при поступлении, режим уточняется. На сколько отделов нужно раскладывать письма?"}, {"role": "user", "content": "Отделов около 12, точный список у меня есть."}, {"role": "assistant", "content": "12 отделов, список у инициатора. Что делать с письмом, если модель не уверена?"}, {"role": "user", "content": "Оставлять в общей очереди, как сейчас."}, {"role": "assistant", "content": "Fallback — общая очередь. Есть ли размеченная история писем для обучения?"}, {"role": "user", "content": "Не знаю, надо спросить у ИТ."}, {"role": "assistant", "content": "Фиксирую открытым вопросом. В письмах есть персональные данные или банковская тайна?"}, {"role": "user", "content": "Конечно, там реквизиты счетов, иногда паспортные данные директоров."}, {"role": "assistant", "content": "Фиксирую: ПДн и банковская тайна; класс данных уточняется с ИБ. Как поймём, что сервис работает хорошо?"}, {"role": "user", "content": "Чтобы письма быстрее попадали в нужный отдел. Цифр нет."}, {"role": "assistant", "content": "Записал: метрика — время до попадания письма в отдел, целевые значения TBD. Резюме: новая модель классификации писем юрлиц на ~12 отделов, ~3000 писем в день; режим (сразу или пачками) уточняется; fallback — общая очередь; MLflow и GitLab — открытые пункты; применимость SRV-004 не проверена; разметка — неизвестно; ПДн и банковская тайна, класс уточняется; метрика без цифр. Всё верно?"}, {"role": "user", "content": "Да."}, {"role": "assistant", "content": "Спасибо! Формирую BRD."}]}, {"run": 4, "username": "eval: руководитель клиентского сервиса корпоративного блока", "history": [{"role": "assistant", "content": "Здравствуйте! Я BRD-ассистент команды развития ИИ-среды. Помогу сформулировать требования к вашей задаче и подготовлю по ним BRD. Для начала расскажите в двух словах: какую задачу вы хотите решить?"}, {"role": "user", "content": "Хотим подключить ChatGPT, чтобы он делал краткие выжимки переписки менеджеров с корпоративными клиентами."}, {"role": "assistant", "content": "Понял задачу — суммаризация переписки. Сразу отмечу: банк работает в полностью закрытом контуре, вызовы внешних моделей вроде ChatGPT за периметр не выходят. Это конфликтует с базовым ограничением и попадёт в BRD как риск. Где ведётся переписка?"}, {"role": "user", "content": "В корпоративном мессенджере и почте. А почему нельзя ChatGPT? Он же лучший."}, {"role": "assistant", "content": "Требование контура — ни один вызов к внешней модели или API не выходит за периметр. Предложение зафиксирую как риск, решение остаётся за архитекторами и ИБ. В реестре есть SRV-012 «Суммаризация звонков контакт-центра» на on-prem LLM, пилот. Не рассматривали его для переписки?"}, {"role": "user", "content": "Нет, не знали о нём. Можно посмотреть."}, {"role": "assistant", "content": "Фиксирую: проверить переиспользование SRV-012. Кто будет читать выжимки и зачем?"}, {"role": "user", "content": "Руководители групп, чтобы быстро понимать, что происходит с клиентом, перед встречей."}, {"role": "assistant", "content": "Понял. Как часто нужны выжимки?"}, {"role": "user", "content": "Раз в день по каждому клиенту, у которого была переписка, это около 500 клиентов."}, {"role": "assistant", "content": "Batch раз в сутки, ~500 клиентов. Есть ли уже модель или код?"}, {"role": "user", "content": "Нет, ничего нет. Мы думали просто использовать ChatGPT."}, {"role": "assistant", "content": "Значит, MLflow и GitLab — открытые пункты. Какие данные попадут в модель?"}, {"role": "user", "content": "Тексты переписки, там суммы сделок, условия кредитов, иногда ПДн."}, {"role": "assistant", "content": "Фиксирую: коммерческие условия, банковская тайна, ПДн; класс данных — открытый вопрос к ИБ. Как поймём, что выжимки полезны?"}, {"role": "user", "content": "Руководители будут тратить на подготовку к встрече меньше времени. Сейчас около часа."}, {"role": "assistant", "content": "Записал: сейчас ~1 ч на подготовку, целевое значение TBD. Резюме: ежедневная суммаризация переписки по ~500 корпоративным клиентам для руководителей групп; инициатор предлагал ChatGPT — конфликт с закрытым контуром, фиксируется как риск; возможное переиспользование SRV-012 (on-prem LLM); модели и кода нет; данные — переписка с банковской тайной и ПДн, класс уточняется с ИБ; метрика — время подготовки (сейчас ~1 ч). Всё верно?"}, {"role": "user", "content": "Да, верно."}, {"role": "assistant", "content": "Спасибо! Формирую BRD."}]}, {"run": 5, "username": "eval: аналитик CRM-маркетинга", "history": [{"role": "assistant", "content": "Здравствуйте! Я BRD-ассистент команды развития ИИ-среды. Помогу сформулировать требования к вашей задаче и подготовлю по ним BRD. Для начала расскажите в двух словах: какую задачу вы хотите решить?"}, {"role": "user", "content": "Нам нужен прогноз оттока розничных клиентов, чтобы запускать кампании удержания."}, {"role": "assistant", "content": "Понял. В реестре действующих сервисов есть SRV-002 «Прогноз оттока розничных клиентов» — batch, еженедельно по понедельникам, результат в витрину CRM для кампаний удержания. Похоже, это ровно ваша задача. Вы пользуетесь им?"}, {"role": "user", "content": "Ой, да, кажется пользуемся. Но нам бы хотелось добавить новые признаки — поведение в мобильном приложении."}, {"role": "assistant", "content": "Значит, речь о доработке существующей модели SRV-002, а не о новом сервисе. Кто владелец модели и есть ли у DS уже версия с новыми признаками?"}, {"role": "user", "content": "Не знаю, кто владелец. Версии с новыми признаками нет."}, {"role": "assistant", "content": "Фиксирую: владелец и новая версия — открытые вопросы. Новая версия будет залогирована в MLflow, а код — в GitLab?"}, {"role": "user", "content": "Не знаю, наверное, как обычно."}, {"role": "assistant", "content": "Записал как открытый пункт: подтвердить MLflow и GitLab для новой версии. Откуда брать данные мобильного приложения?"}, {"role": "user", "content": "Не знаю, это у ИТ."}, {"role": "assistant", "content": "Фиксирую открытым вопросом: источник и владелец данных приложения. Как поймём, что новая версия лучше текущей?"}, {"role": "user", "content": "Отток должен снизиться, но цифр пока нет."}, {"role": "assistant", "content": "Записал: метрика без целевого значения, нужен baseline текущей версии. Резюме: доработка существующего SRV-002 (добавить признаки поведения в мобильном приложении), не новый сервис; владелец модели, новая версия, MLflow/GitLab, источник данных и целевые метрики — открытые вопросы. Всё верно?"}, {"role": "user", "content": "Да, всё так."}, {"role": "assistant", "content": "Спасибо! Формирую BRD."}]}];
const now = new Date().toISOString();
const stamp = Date.now().toString(36);
return T.map((t) => ({ json: {
  session_id: `eval-${t.run}-${stamp}`, chat_id: `eval-${t.run}`, user_id: '', username: t.username,
  status: 'eval_ready', history: JSON.stringify(t.history.map((m) => ({ ...m, ts: now }))),
  turn_count: t.history.filter((m) => m.role === 'user').length, started_at: now, last_activity_at: now,
  reminder_count: 0, last_reminder_at: '', brd_title: '', brd_url: '', error: '',
  cost_usd: 0, limit_hit: '', brd_attempts: 0, brd_created_at: '', brd_draft: '', brd_draft_title: '',
} }));
